sub _census {
    my ($base) = @_;
    my $images = _names("$base/images", $IMAGE_LIMIT);
    my $references = _names("$base/references", $REFERENCE_LIMIT);
    for my $name (@$images) {
        die "invalid image name\n" unless $name =~ /\A[0-9a-f]{64}\z/;
        NativeProxyImageCustody::_directory("$base/images/$name");
    }
    for my $name (@$references) {
        die "invalid reference name\n" unless $name =~ /\A[0-9a-f]{64}\.json\z/;
        my $source = NativeProxyImageCustody::_source("$base/references/$name", 0400, 4096);
        my $ok = eval { NativeProxyImageCustody::_recheck_source($source); 1 };
        my $error = $@;
        my $closed = close($source->{handle});
        die $error unless $ok;
        die "cannot close census reference: $!\n" unless $closed;
    }
    # Count incomplete image/record objects. This structure-only result cannot
    # establish complete image contents or reference schema/lifetime validity.
    return {images => $images, references => $references};
}

sub _source {
    my ($path, $mode, $limit) = @_;
    # Reuse the qualified bounded no-follow descriptor read. The additional
    # custody checks below enforce this store's stricter modes and link count.
    my ($bytes, $metadata, $handle) = FSM::Test::RustProxyFixture::_read_file($path, 1);
    my $ok = eval {
        die "invalid image source mode, links or size\n"
            unless ($metadata->[2] & 07777) == $mode && $metadata->[3] == 1
                && length($bytes) <= $limit;
        my $flags = fcntl($handle, F_GETFD, 0);
        die "cannot read descriptor flags: $!\n" unless defined $flags;
        fcntl($handle, F_SETFD, $flags | FD_CLOEXEC)
            or die "cannot seal descriptor inheritance: $!\n";
        1;
    };
    my $error = $@;
    unless ($ok) {
        # The lower reader transferred ownership even when these stricter
        # checks fail. Close that handle explicitly and preserve the cause.
        close($handle);
        die $error;
    }
    return {bytes => $bytes, metadata => $metadata, handle => $handle, path => $path};
}

sub _recheck_source {
    my ($source) = @_;
    my @descriptor = stat($source->{handle});
    my @named = lstat($source->{path});
    die "source descriptor or named identity changed\n"
        unless _same_metadata($source->{metadata}, \@descriptor, 0,1,2,3,4,7,9,10)
            && _same_metadata($source->{metadata}, \@named, 0,1,2,3,4,7,9,10)
            && S_ISREG($named[2]);
}

sub _read_file {
    my ($path, $keep_open) = @_;
    my ($absolute, $error) = repository_contained_path($path, must_exist => 1);
    die "$error\n" if defined $error;
    sysopen(my $fh, $absolute, O_RDONLY | O_NOFOLLOW | O_NONBLOCK) or die "cannot read fixture: $!\n";
    binmode($fh);
    my @before = stat($fh);
    die "fixture must be an owned bounded regular file\n"
        unless @before && S_ISREG($before[2]) && $before[4] == $<
            && $before[0] == (stat($ROOT))[0] && $before[7] <= $LIMIT;
    my $body = '';
    while (length($body) <= $LIMIT) {
        my $count = sysread($fh, my $chunk, $LIMIT + 1 - length($body));
        die "cannot read fixture bytes: $!\n" unless defined $count;
        last unless $count;
        $body .= $chunk;
    }
    my @after = stat($fh);
    my @named = lstat($absolute);
    die "fixture changed during its bounded read\n"
        unless @after && @named && length($body) == $before[7] && length($body) <= $LIMIT
            && join(':', @before[0,1,2,4,7,9,10]) eq join(':', @after[0,1,2,4,7,9,10])
            && join(':', @before[0,1,2,4,7,9,10]) eq join(':', @named[0,1,2,4,7,9,10]);
    close($fh) or die "cannot close fixture: $!\n" unless $keep_open;
    return ($body, \@before, $keep_open ? $fh : undef);
}
